import{_ as a,o as e,c as n,a6 as t}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"流式渲染 · 别等全部，边算边发","description":"传统 SSR 必须等整页渲染完才能发出第一个字节——一个慢查询拖垮整页。流式渲染让服务器先发出外壳，再把慢的区块「边算边发」流式补上，TTFB 大降、首屏更快。这一章讲清它的原理与 Suspense。","frontmatter":{"title":"流式渲染 · 别等全部，边算边发","description":"传统 SSR 必须等整页渲染完才能发出第一个字节——一个慢查询拖垮整页。流式渲染让服务器先发出外壳，再把慢的区块「边算边发」流式补上，TTFB 大降、首屏更快。这一章讲清它的原理与 Suspense。","source":"https://daiw.org/manual/ssr/streaming"},"headers":[],"relativePath":"manual/computer-programming/ssr/streaming.md","filePath":"manual/computer-programming/ssr/streaming.md"}'),i={name:"manual/computer-programming/ssr/streaming.md"};function r(l,s,o,p,d,h){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="流式渲染-·-别等全部-边算边发" tabindex="-1">流式渲染 · 别等全部，边算边发 <a class="header-anchor" href="#流式渲染-·-别等全部-边算边发" aria-label="Permalink to &quot;流式渲染 · 别等全部，边算边发&quot;">​</a></h1><p>传统 SSR 必须等整页渲染完才能发出第一个字节——一个慢查询拖垮整页。流式渲染让服务器先发出外壳，再把慢的区块「边算边发」流式补上，TTFB 大降、首屏更快。这一章讲清它的原理与 Suspense。</p><p>传统 SSR 有个致命节奏问题：<strong>必须等整个页面渲染完，才能发出第一个字节。</strong></p><p>想象一个页面：顶部导航、中间是要查数据库的商品列表、底部是要调第三方 API 的推荐位。传统 SSR 会<strong>傻等</strong>——等最慢的那个（比如卡了 800ms 的推荐 API）也返回、整页 HTML 全部拼好，才把第一个字节发给浏览器。于是<strong>一个慢区块，拖垮了整页的 TTFB</strong>。导航明明瞬间就能给，却要陪着推荐位一起等。</p><p><strong>流式渲染(streaming SSR)</strong> 解决的正是这个：<strong>先发能发的，慢的随后补。</strong></p><h2 id="边算边发" tabindex="-1">边算边发 <a class="header-anchor" href="#边算边发" aria-label="Permalink to &quot;边算边发&quot;">​</a></h2><p>流式的思路是把 HTML 拆成一块块，<strong>谁先就绪就先发谁</strong>：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;请求到达&quot;] --&gt; B[&quot;立即发出 HTML 外壳&lt;br/&gt;导航 · 布局 · 骨架&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[&quot;慢区块先发一个占位&lt;br/&gt;(loading 骨架)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[&quot;数据就绪后&lt;br/&gt;把真实内容流式补进去&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>浏览器一拿到外壳就能<strong>立刻画出导航和骨架</strong>（TTFB 极短），用户马上看到「页面在动」；那些慢的区块先显示 loading 占位，等服务端数据就绪，再通过<strong>同一条 HTTP 响应流</strong>把真实内容推过去，自动替换掉占位。<strong>一个慢查询，不再拖累其余部分。</strong></p><h2 id="suspense-声明「这块可以晚点来」" tabindex="-1">Suspense：声明「这块可以晚点来」 <a class="header-anchor" href="#suspense-声明「这块可以晚点来」" aria-label="Permalink to &quot;Suspense：声明「这块可以晚点来」&quot;">​</a></h2><p>在 React 里，流式的开关是 <strong><code>&lt;Suspense&gt;</code></strong>。你用它把「可能会慢」的区块包起来，并给个 <code>fallback</code>（占位）：</p><div class="language-jsx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Layout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Nav</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;                          {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 立刻就绪,先发 */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Suspense</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fallback</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Skeleton</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;}&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SlowProductList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;            {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 慢,先发 Skeleton,就绪后流式补上 */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Suspense</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Layout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>服务端用 <code>renderToPipeableStream</code>（而非老的 <code>renderToString</code>）渲染：遇到 <code>&lt;Suspense&gt;</code>，它<strong>不阻塞</strong>——先把 <code>fallback</code> 连同外壳发出去，等 <code>&lt;SlowProductList&gt;</code> 的数据好了，再把真实 HTML 作为后续 chunk 流式发送，并附一小段脚本把占位替换掉。<strong><code>&lt;Suspense&gt;</code> 就是你对框架说的那句「这块可以晚点来，别等它」。</strong></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>各框架都有自己的「Suspense 式」出口：Next.js App Router 用 <code>&lt;Suspense&gt;</code> 和 <code>loading.js</code>（整个路由段的流式占位）；React Router v7（原 Remix，早期用 <code>defer()</code>）的 <code>loader</code> 与 SvelteKit 的 <code>load</code> 都支持直接返回未 <code>await</code> 的 Promise，配合 <code>&lt;Await&gt;</code> / <code>{#await}</code> 让页面先渲染。名字不同，做的是同一件事：<strong>声明哪些区块允许「先占位、后补上」。</strong></p></div><h2 id="流式还顺带改善了水合" tabindex="-1">流式还顺带改善了水合 <a class="header-anchor" href="#流式还顺带改善了水合" aria-label="Permalink to &quot;流式还顺带改善了水合&quot;">​</a></h2><p>流式不只让<strong>首屏</strong>更快，还让<a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a>更聪明——这叫<strong>选择性水合(selective hydration)</strong>:</p><ul><li>流式发来的区块，可以<strong>各自独立地水合</strong>，不必等整页 HTML 全到齐。</li><li>React 会<strong>优先水合用户正在交互的区块</strong>——你点了哪儿，它就先「激活」哪儿，而不是死板地从上到下。</li></ul><p>于是<a href="/Front2Full/manual/computer-programming/ssr/hydration">上一章那个「看得见点不动」的空档</a>，被大大压缩了：内容一块块地到达、一块块地变得可交互，而不是「整页一起卡着等水合」。</p><h2 id="代价与注意点" tabindex="-1">代价与注意点 <a class="header-anchor" href="#代价与注意点" aria-label="Permalink to &quot;代价与注意点&quot;">​</a></h2><p>流式不是纯赚，有几处要留心：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>① <strong>状态码和响应头必须先发。</strong> HTTP 响应的头部（状态码、<code>Content-Type</code>、以及后面要讲的<strong>缓存头</strong>）在流开始时就得定下来——因为第一个字节已经发出去了，你没法「发到一半改成 500」。这对错误处理和缓存策略有实际影响。 ② <strong>一旦开始流，就难以整体缓存。</strong> 一个流式响应是「边生成边发」的，想把它当成一个完整对象缓存起来，比缓存一份定死的 HTML 要复杂——这是流式和 <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">CDN 缓存</a> 之间的一处张力，后面会再提。 ③ <strong>SEO 要确认爬虫等得到。</strong> 流式补上的内容是后到的，得确认目标爬虫会等完整个流（主流搜索引擎会，但一些简单爬虫可能只取先到的外壳）。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>流式渲染把「等整页渲染完才发」改成「先发外壳、慢区块随后流式补上」，TTFB 大降、首屏更快，还借选择性水合缓解了「看得见点不动」。代价是响应头要提前定、整体缓存变复杂。它解决的是「<strong>什么时候发</strong>」。</p><p>但还有个更根本的开销没动：<a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a>要把<strong>所有</strong>组件在客户端再跑一遍、把<strong>所有</strong>组件 JS 都发给浏览器。有没有办法让<strong>一部分组件根本不发到客户端、根本不水合</strong>？这就是服务端组件与岛屿架构的思路。👉 <a href="/Front2Full/manual/computer-programming/ssr/server-components">服务端组件：只在服务端跑的那部分</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] React 官方文档.「renderToPipeableStream / Suspense.」<a href="https://react.dev/reference/react-dom/server/renderToPipeableStream" target="_blank" rel="noreferrer">https://react.dev/reference/react-dom/server/renderToPipeableStream</a> —— 流式 API 与选择性水合。</li><li>[2] Next.js 文档.「Loading UI and Streaming.」<a href="https://nextjs.org/docs/app/building-your-application/routing/loading-ui-and-streaming" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/routing/loading-ui-and-streaming</a> —— 框架层的流式。</li><li>[3] web.dev.「Streaming server-side rendering.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— 流式 SSR 的动机与收益。</li></ul>`,26)])])}const k=a(i,[["render",r]]);export{c as __pageData,k as default};
